/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_FINTXN_HEADER
   anchor      : HUB_FINANCIAL_TRANSACTION   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 3 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_FINANCIAL_TRANSACTION_HK
   hashdiff    : SAT_FINTXN_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 1 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     ORIGINATING_SYSTEM_REFERENCE           opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID))) as HUB_FINANCIAL_TRANSACTION_HK
        , REMARKS as NARRATION
        , ORDER_NUMBER as SOURCE_REFERENCE_NUMBER
        , BANCA_REF_ID as ORIGINATING_SYSTEM_REFERENCE
        , cast(null as varchar) as TRANSACTION_DATE
        , cast(null as varchar) as GROSS_AMOUNT
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(PTRANSACTION_ID),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NARRATION end) as NARRATION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SOURCE_REFERENCE_NUMBER end) as SOURCE_REFERENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ORIGINATING_SYSTEM_REFERENCE end) as ORIGINATING_SYSTEM_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TRANSACTION_DATE end) as TRANSACTION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GROSS_AMOUNT end) as GROSS_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when NARRATION is not null or SOURCE_REFERENCE_NUMBER is not null or ORIGINATING_SYSTEM_REFERENCE is not null or TRANSACTION_DATE is not null or GROSS_AMOUNT is not null
                     then md5(upper(coalesce(cast(NARRATION as varchar), '') || '|' || coalesce(cast(SOURCE_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(ORIGINATING_SYSTEM_REFERENCE as varchar), '') || '|' || coalesce(cast(TRANSACTION_DATE as varchar), '') || '|' || coalesce(cast(GROSS_AMOUNT as varchar), '')))
                end as SAT_FINTXN_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_HEADER_HASHDIFF is not null
